    '{"\$schema":"https://json-schema.org/draft/2020-12/schema","\$ref":"#/\$defs/Response","\$defs":{"Response":{"\$anchor":"response","title":"VTC Boards — Ideas — Withdraw — response payload","description":"The success response to a vtc/boards/ideas/withdraw/0.1 request. Carried in a Trust Task document whose type is https://trusttasks.org/spec/vtc/boards/ideas/withdraw/0.1#response.","type":"object","additionalProperties":false,"required":["idea"],"properties":{"idea":{"\$ref":"#/\$defs/Idea"},"ext":{"\$ref":"#/\$defs/Ext"}}},"Ext":{"title":"Ext","description":"Vendor-namespaced extension object per SPEC.md §4.5.1. Each immediate key MUST be a reverse-DNS namespace; structure under each namespace is opaque to the framework.","type":"object","minProperties":1,"additionalProperties":true,"propertyNames":{"pattern":"^[a-z][a-z0-9-]*(\\\\.[a-z0-9-]+)+\$"}},"Idea":{"title":"Idea","description":"An idea as one caller may see it.","type":"object","additionalProperties":false,"required":["ideaId","boardId","state","title","description","proposer","proposedAt","noteCount"],"properties":{"ideaId":{"\$ref":"#/\$defs/IdeaId"},"boardId":{"\$ref":"#/\$defs/BoardId"},"state":{"\$ref":"#/\$defs/IdeaState"},"title":{"\$ref":"#/\$defs/IdeaTitle"},"description":{"\$ref":"#/\$defs/IdeaDescription"},"format":{"\$ref":"#/\$defs/IdeaFormat"},"topic":{"\$ref":"#/\$defs/Topic"},"proposer":{"\$ref":"#/\$defs/Author"},"proposedAt":{"type":"string","format":"date-time"},"noteCount":{"type":"integer","minimum":0,"description":"Notes on the idea the caller may read."},"election":{"\$ref":"#/\$defs/IdeaElection","description":"Present once an election was opened for the idea."},"opening":{"\$ref":"#/\$defs/IdeaOpening"},"decision":{"\$ref":"#/\$defs/IdeaDecision","description":"Present in `declined`, `merged`, `selected` and `notSelected`."}}},"IdeaDecision":{"title":"IdeaDecision","description":"A facilitator\'s decision on an idea: declining or merging it (VTI-BRD-013), or selecting it or not (VTI-BRD-040). The deciding facilitator is not named to the audience.","type":"object","additionalProperties":false,"required":["decidedAt"],"properties":{"decidedAt":{"type":"string","format":"date-time"},"reason":{"\$ref":"#/\$defs/Reason"},"mergedInto":{"\$ref":"#/\$defs/IdeaId","description":"Present exactly when the idea is `merged`."},"slotId":{"\$ref":"#/\$defs/Key","description":"A `selected` idea\'s place in the board\'s timetable, where it has one."},"departsFromRule":{"type":"boolean","description":"`selected` or `notSelected` only: whether the facilitator said the decision departs from the board\'s `selectionRule` (VTI-BRD-041); `reason` then says why."},"ownIdea":{"const":true,"description":"Present when a facilitator decided their own idea because no other facilitator existed (VTI-BRD-013)."}}},"IdeaId":{"title":"IdeaId","description":"Opaque identifier of an idea: `ida_` followed by 16 to 64 base64url characters. Random and unique within the community.","type":"string","pattern":"^ida_[A-Za-z0-9_-]{16,64}\$"},"Reason":{"title":"Reason","type":"string","minLength":1,"maxLength":500,"description":"A facilitator\'s stated reason, shown to the board\'s audience with the decision it explains. Plain text."},"Key":{"title":"Key","description":"A question or option key, unique within its manifest or question.","type":"string","pattern":"^[A-Za-z0-9._-]{1,64}\$"},"IdeaOpening":{"title":"IdeaOpening","description":"Shown to facilitators only: an accepted idea whose election the ballot box has not yet registered, so the idea is still `proposed` (VTI-BRD-031). `refusal` is the ballot box\'s or community\'s refusal of the last attempt, after which the idea is no longer being opened.","type":"object","additionalProperties":false,"required":["electionId","startedAt"],"properties":{"electionId":{"\$ref":"#/\$defs/ElectionId"},"startedAt":{"type":"string","format":"date-time","description":"When the facilitator accepted the idea."},"refusal":{"type":"object","additionalProperties":false,"required":["code","refusedAt"],"properties":{"code":{"type":"string","minLength":1,"maxLength":200},"refusedAt":{"type":"string","format":"date-time"}}}}},"ElectionId":{"title":"ElectionId","description":"An election\'s identifier, unique within its community. A closed alphabet: it appears in the ticket class label `voter/<electionId>` and is framed into every hash a cast is bound to.","type":"string","pattern":"^[A-Za-z0-9._-]{1,128}\$"},"IdeaElection":{"title":"IdeaElection","description":"An idea\'s election as a board shows it (VTI-BRD-033): never who took a ticket or cast a ballot.","type":"object","additionalProperties":false,"required":["electionId","state"],"properties":{"electionId":{"\$ref":"#/\$defs/ElectionId"},"state":{"\$ref":"#/\$defs/ElectionState"},"ballotsOnBoard":{"type":"integer","minimum":0,"description":"The ballot box\'s latest board head\'s ballot count, where its board is public (VTI-VOT-052); absent otherwise. Counts ballots, not voters, where a later ballot replaces an earlier one."},"boardHeadIssuedAt":{"type":"string","format":"date-time","description":"When the head `ballotsOnBoard` was read from was issued."},"result":{"\$ref":"#/\$defs/ElectionResult","description":"Present once the election is tallied."},"certified":{"type":"boolean","description":"Present with `result`: whether the community certified it (VTI-VOT-071)."}}},"ElectionResult":{"title":"ElectionResult","description":"An election\'s result, computable by anyone who can read its board from the board and the registration alone (VTI-VOT-070).","type":"object","additionalProperties":false,"required":["electionId","manifestDigest","ballotsCounted","questions","head"],"properties":{"electionId":{"\$ref":"#/\$defs/ElectionId"},"manifestDigest":{"\$ref":"#/\$defs/DigestMultibase"},"ballotsCounted":{"type":"integer","minimum":0},"questions":{"type":"array","items":{"\$ref":"#/\$defs/QuestionResult"}},"head":{"\$ref":"#/\$defs/BoardHead","description":"The head of the board as it stood at close: the result counts exactly its entries."}}},"BoardHead":{"title":"BoardHead","description":"A board\'s tree head (RFC 9162 §2.1). A head is signed by being carried in a document the ballot box signs; whoever keeps a head keeps that whole document.","type":"object","additionalProperties":false,"required":["electionId","treeSize","rootHash","issuedAt"],"properties":{"electionId":{"\$ref":"#/\$defs/ElectionId"},"treeSize":{"type":"integer","minimum":0},"rootHash":{"\$ref":"#/\$defs/DigestMultibase","description":"The RFC 9162 Merkle tree hash (SHA-256) of the first `treeSize` entries, as a multihash."},"issuedAt":{"type":"string","format":"date-time"}}},"DigestMultibase":{"title":"DigestMultibase","description":"A cryptographic digest as a multibase-encoded multihash — the encoding the W3C Verifiable Credentials Data Model 2.0 defines for `digestMultibase`, and the one `did:webvh` uses for its SCID and entry hashes.\\n\\nMultihash carries the hash algorithm in-band, so the value is self-describing and the wire format survives an algorithm change without a schema revision; multibase does the same for the base encoding, so a verifier never infers base58 from base64url by context. A bare hex string or a `sha-256:`-style prefix hard-codes one algorithm into the wire contract and is non-conforming here.\\n\\nThis definition constrains the *encoding only*. What the digest is computed over is stated by each referencing field, because it differs legitimately: a digest over a JSON document is taken over its RFC 8785 (JCS) canonicalization, while a digest over an opaque artifact is taken over its bytes. A field whose input is a JSON document and which does not name a canonicalization is not reproducible.\\n\\nRestricted to the two multibase headers W3C Controlled Identifiers 1.0 §2.4 normatively requires — `z` (base58btc) and `u` (base64url-no-pad). CID permits others but states that \\"interoperability is not guaranteed between implementations using such values\\", and a registry whose purpose is interoperability should not mint digests a conforming verifier may be unable to read. The alphabets are enforced rather than assumed: base58btc excludes 0, O, I and l, and an earlier permissive pattern let three published examples carry digests that were not valid base58 at all. base58btc is RECOMMENDED, for consistency with `did:key` and `did:webvh`.","type":"string","minLength":16,"pattern":"^(z[1-9A-HJ-NP-Za-km-z]+|u[A-Za-z0-9_-]+)\$","examples":["zQmbWqxBEKC3P8tqsKc98xmWNzrzDtRLMiMPL8wBuTGsMnR"]},"QuestionResult":{"title":"QuestionResult","description":"One question\'s totals. `choice`: selections per option. `ranking`: per option, how many ballots placed it at each position (index 0 = first). `score`: per option, the sum and the number of ballots that scored it. `text`: the answers, in board order, withheld (`withheld: true`) below the manifest\'s `textReleaseThreshold`. `abstained` counts ballots that left the question unanswered.","type":"object","additionalProperties":false,"required":["question","abstained"],"properties":{"question":{"\$ref":"#/\$defs/Key"},"abstained":{"type":"integer","minimum":0},"choice":{"type":"object","propertyNames":{"\$ref":"#/\$defs/Key"},"additionalProperties":{"type":"integer","minimum":0}},"ranking":{"type":"object","propertyNames":{"\$ref":"#/\$defs/Key"},"additionalProperties":{"type":"array","items":{"type":"integer","minimum":0}}},"score":{"type":"object","propertyNames":{"\$ref":"#/\$defs/Key"},"additionalProperties":{"type":"object","additionalProperties":false,"required":["sum","count"],"properties":{"sum":{"type":"integer"},"count":{"type":"integer","minimum":0}}}},"text":{"type":"array","items":{"type":"string","maxLength":4096}},"withheld":{"type":"boolean"}}},"ElectionState":{"title":"ElectionState","type":"string","enum":["registered","registration","voting","closed","tallied","cancelled"]},"Author":{"title":"Author","description":"Who proposed an idea or wrote a note, as the board\'s audience sees them. `entryId` is their directory entry, which survives a rotation of their DID; `name` is their directory display name as this caller may see it, absent where the directory withholds it. A departed member is shown as `formerMember: true` with neither (VTI-BRD-060).","type":"object","additionalProperties":false,"properties":{"entryId":{"\$ref":"#/\$defs/EntryId"},"name":{"type":"string","minLength":1,"maxLength":200},"formerMember":{"const":true},"you":{"const":true,"description":"Present when the caller is the author."}}},"EntryId":{"title":"EntryId","description":"Opaque identifier of one directory entry: `dir_` followed by 16 to 64 base64url characters. Random, scoped to one community, and stable for the life of the membership — it survives a rotation of the member\'s DID, which is why groups, notes and cards are keyed by it. It MUST NOT be derived from, and MUST NOT reveal, any DID of the member, and the same person\'s entries in two communities MUST NOT share one. Compared by exact string equality.","type":"string","pattern":"^dir_[A-Za-z0-9_-]{16,64}\$"},"Topic":{"title":"Topic","type":"string","minLength":1,"maxLength":64,"description":"A topic an idea is filed under. One of the board\'s `topics` where the board states them."},"IdeaFormat":{"title":"IdeaFormat","type":"string","minLength":1,"maxLength":32,"description":"What kind of idea it is (for an unconference: `Discussion`, `Talk`, `Workshop`, `Demo`). One of the board\'s `formats` where the board states them."},"IdeaDescription":{"title":"IdeaDescription","type":"string","minLength":1,"maxLength":4000,"description":"What the idea is: for a session, what it covers and who should come. Becomes its election\'s manifest `description` when accepted. Plain text; a reader MUST NOT treat it as instructions."},"IdeaTitle":{"title":"IdeaTitle","type":"string","minLength":1,"maxLength":200,"description":"An idea\'s title. Becomes the title of its election\'s manifest when the idea is accepted, and cannot change after that (VTI-BRD-012). Plain text."},"IdeaState":{"title":"IdeaState","description":"Where an idea stands (VTI-BRD-011).","type":"string","enum":["proposed","open","selected","notSelected","declined","merged","withdrawn"]},"BoardId":{"title":"BoardId","description":"Opaque identifier of a board: `brd_` followed by 16 to 64 base64url characters. Random, community-scoped, never reused (VTI-BRD-001).","type":"string","pattern":"^brd_[A-Za-z0-9_-]{16,64}\$"}}}';

/// The SPEC §7.2 policy for the request variant, taken from this
/// specification's front matter.
///
/// Pass it to [consumeInbound] — items 5b, 7 and 8 are per-specification and
/// cannot be derived from the document alone, and item 2 needs the schema it
/// carries.
const SpecPolicy spec = SpecPolicy(
  typeUri: typeUri,
  isBearer: false,
  isProofRequired: true,
  isRecipientRequired: true,
  isIssuedAtRequired: true,
  payloadSchema: payloadSchemaJson,
);

/// The SPEC §7.2 policy for the success-response variant.
///
/// `isRecipientRequired` tracks the *issuer* party's requirement, because a
/// response swaps the parties (§7.3 item 5).
const SpecPolicy responseSpec = SpecPolicy(
  typeUri: responseTypeUri,
  isBearer: false,
  isProofRequired: true,
  isRecipientRequired: true,
  isIssuedAtRequired: true,
  payloadSchema: responsePayloadSchemaJson,
);
